#!/usr/bin/env node

/**
 * UAT Reset Preview Script
 * Shows what WOULD be deleted without modifying anything
 * Author: Generated by Claude Code
 * Date: 2026-08-31
 */

import { createClient } from '@supabase/supabase-js'
import { loadEnv, validateEnv } from './lib/load-env.mjs'

// Load environment variables
loadEnv()

// Validate required variables
const config = validateEnv()

// ============================================================================
// CONFIGURATION
// ============================================================================

const KEEP_SUPER_ADMIN_EMAIL = config.keepSuperAdminEmail

// Create Supabase admin client (server-side only)
const supabase = createClient(config.supabaseUrl, config.serviceRoleKey, {
  auth: {
    persistSession: false,
    autoRefreshToken: false,
  },
})

// ============================================================================
// MAIN
// ============================================================================

async function main() {
  try {
    console.log('='.repeat(80))
    console.log('WISPER UAT RESET — PREVIEW')
    console.log('='.repeat(80))
    console.log('')

    // ========================================================================
    // 1. SUPER_ADMIN TO KEEP
    // ========================================================================

    const { data: superAdmins, error: superAdminError } = await supabase
      .from('profiles')
      .select('id, full_name, email, is_active, role')
      .eq('role', 'SUPER_ADMIN')
      .ilike('email', KEEP_SUPER_ADMIN_EMAIL.trim())

    console.log('SUPER_ADMIN TO KEEP')
    console.log('-'.repeat(80))

    if (superAdminError) {
      throw new Error(`Failed to query profiles: ${superAdminError.message}`)
    }

    if (!superAdmins || superAdmins.length === 0) {
      console.log('❌ NOT FOUND:', KEEP_SUPER_ADMIN_EMAIL)
      console.log('')
      console.log('⚠️  WARNING: Reset will FAIL if SUPER_ADMIN not found')
      console.log('')
    } else if (superAdmins.length > 1) {
      console.log('❌ ERROR: Multiple SUPER_ADMINs with email:', KEEP_SUPER_ADMIN_EMAIL)
      console.log('')
    } else {
      const admin = superAdmins[0]
      console.log('✅ Email:', admin.email)
      console.log('   Profile ID:', admin.id)
      console.log('   Name:', admin.full_name)
      console.log('   Active:', admin.is_active)

      // Check auth user
      const { data: authUser, error: authError } = await supabase.auth.admin.getUserById(admin.id)
      if (authError) {
        console.log('   Auth User: ❌ NOT FOUND')
      } else {
        console.log('   Auth User ID:', authUser.user.id)
        console.log('   Email confirmed:', !!authUser.user.email_confirmed_at)
      }
      console.log('')
    }

    // ========================================================================
    // 2. DATABASE COUNTS
    // ========================================================================

    console.log('DATABASE')
    console.log('-'.repeat(80))

    // Count profiles by role
    const { count: totalProfiles } = await supabase
      .from('profiles')
      .select('*', { count: 'exact', head: true })

    const { count: admins } = await supabase
      .from('profiles')
      .select('*', { count: 'exact', head: true })
      .eq('role', 'ADMIN')

    const { count: technicians } = await supabase
      .from('profiles')
      .select('*', { count: 'exact', head: true })
      .eq('role', 'TECHNICIAN')

    // Count other tables
    const { count: technicianRecords } = await supabase
      .from('technicians')
      .select('*', { count: 'exact', head: true })

    const { count: clients } = await supabase
      .from('clients')
      .select('*', { count: 'exact', head: true })

    const { count: tickets } = await supabase
      .from('tickets')
      .select('*', { count: 'exact', head: true })

    const { count: activities } = await supabase
      .from('ticket_activity')
      .select('*', { count: 'exact', head: true })

    const { count: statusHistory } = await supabase
      .from('ticket_status_history')
      .select('*', { count: 'exact', head: true })

    const { count: evidences } = await supabase
      .from('ticket_evidences')
      .select('*', { count: 'exact', head: true })

    const { count: signatures } = await supabase
      .from('ticket_signatures')
      .select('*', { count: 'exact', head: true })

    const { count: pushTokens } = await supabase
      .from('technician_push_tokens')
      .select('*', { count: 'exact', head: true })

    const { count: locations } = await supabase
      .from('technician_locations')
      .select('*', { count: 'exact', head: true })

    console.log('Profiles:', totalProfiles || 0)
    console.log('  - Admins:', admins || 0)
    console.log('  - Technicians:', technicians || 0)
    console.log('Technician records:', technicianRecords || 0)
    console.log('Clients:', clients || 0)
    console.log('Tickets:', tickets || 0)
    console.log('Activities:', activities || 0)
    console.log('Status history:', statusHistory || 0)
    console.log('Evidences:', evidences || 0)
    console.log('Signatures:', signatures || 0)
    console.log('Push tokens:', pushTokens || 0)
    console.log('Locations:', locations || 0)
    console.log('')

    // ========================================================================
    // 3. AUTH USERS
    // ========================================================================

    console.log('AUTH')
    console.log('-'.repeat(80))

    const { data: authUsers, error: authListError } = await supabase.auth.admin.listUsers()

    if (authListError) {
      console.log('❌ Failed to list auth users:', authListError.message)
      console.log('')
    } else {
      const total = authUsers.users.length

      // Find users to keep
      const keepUsers = superAdmins
        ? authUsers.users.filter(u => superAdmins.some(sa => sa.id === u.id))
        : []

      const toDelete = total - keepUsers.length

      console.log('Users total:', total)
      console.log('Users to keep:', keepUsers.length)
      console.log('Users to delete:', toDelete)
      console.log('')
    }

    // ========================================================================
    // 4. STORAGE OBJECTS
    // ========================================================================

    console.log('STORAGE')
    console.log('-'.repeat(80))

    const { data: evidenceObjects, error: evidenceError } = await supabase.storage
      .from('ticket-evidences')
      .list('', { limit: 1000 })

    const { data: signatureObjects, error: signatureError } = await supabase.storage
      .from('ticket-signatures')
      .list('', { limit: 1000 })

    console.log('Evidence objects:', evidenceError ? '❌ Error' : (evidenceObjects?.length || 0))
    console.log('Signature objects:', signatureError ? '❌ Error' : (signatureObjects?.length || 0))
    console.log('')

    // ========================================================================
    // 5. VALIDATION
    // ========================================================================

    console.log('VALIDATION')
    console.log('-'.repeat(80))

    const issues = []

    if (!superAdmins || superAdmins.length === 0) {
      issues.push(`SUPER_ADMIN with email ${KEEP_SUPER_ADMIN_EMAIL} not found`)
    }

    if (superAdmins && superAdmins.length > 1) {
      issues.push(`Multiple SUPER_ADMINs with email ${KEEP_SUPER_ADMIN_EMAIL}`)
    }

    if (superAdmins && superAdmins.length === 1) {
      const { data: authUser, error: authError } = await supabase.auth.admin.getUserById(
        superAdmins[0].id
      )
      if (authError || !authUser) {
        issues.push('SUPER_ADMIN profile exists but auth user not found')
      }
    }

    if (issues.length > 0) {
      console.log('❌ ISSUES FOUND:')
      issues.forEach(issue => console.log('   -', issue))
      console.log('')
      console.log('⚠️  Reset will FAIL unless these issues are resolved')
    } else {
      console.log('✅ Validation passed')
      console.log('   Ready to execute reset')
    }

    console.log('')
    console.log('='.repeat(80))
    console.log('NO DATA MODIFIED')
    console.log('='.repeat(80))
    console.log('')

    if (issues.length === 0) {
      console.log('To execute reset:')
      console.log('  UAT_RESET_CONFIRMED=yes npm run uat:reset')
      console.log('  UAT_RESET_CONFIRMED=yes npm run uat:storage:reset')
      console.log('  npm run uat:verify')
      console.log('')
    }
  } catch (error) {
    console.error('❌ Error:', error.message)
    process.exit(1)
  }
}

main()
